2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
27	    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
28	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
32	    Map<String, String> CITY_REGION = Map.of(
33	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /**
36	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
37	     * read-only {@code displayName} field returned on the Owner DTO.
38	     */
39	    default String toDisplayName(Owner owner) {
40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /**
44	     * Build the owner's initials as the upper-cased first letters of firstName and
45	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
46	     * read-only {@code initials} field returned on the Owner DTO.
47	     */
48	    default String toInitials(Owner owner) {
49	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
50	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
51	    }
52	
53	    /**
54	     * Derive the owner's read-only {@code membershipTier}: {@code 'GOLD'} when the owner's household
55	     * had 3 or more members after creation ({@code householdMemberCount} is 3+); otherwise
56	     * {@code 'SILVER'} when the owner's name was unique at creation time ({@code namesakeCount} is 0)
57	     * and an email is present, otherwise {@code 'BRONZE'}.
58	     */
59	    default String toMembershipTier(Owner owner) {
60	        Integer householdMemberCount = owner.getHouseholdMemberCount();
61	        if (householdMemberCount != null && householdMemberCount >= 3) {
62	            return "GOLD";
63	        }
64	        boolean uniqueName = Integer.valueOf(0).equals(owner.getNamesakeCount());
65	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
66	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
67	    }
68	
69	    /**
70	     * Derive the owner's read-only {@code locality}: the canonical region looked up from the
71	     * owner's city in the fixed city-to-region table ({@code Sydney->NSW, Melbourne->VIC,
72	     * Brisbane->QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
73	     */
74	    default String toLocality(Owner owner) {
75	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
76	    }
77	
78	    Owner toOwner(OwnerDto ownerDto);
79	
80	    @Mapping(target = "id", ignore = true)
81	    @Mapping(target = "pets", ignore = true)
82	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
83	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
84	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
85	    Owner toOwner(OwnerFieldsDto ownerDto);
86	
87	    /**
88	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
89	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
90	     * compared in one shape. Blank-after-normalization is rejected separately by
91	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
92	     * value needs.
93	     */
94	    @Named("normalizeAddress")
95	    default String normalizeAddress(String address) {
96	        return AddressNormalizer.normalize(address);
97	    }
98	
99	    /**
100	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
101	     * code and national digits) so it is stored and returned in one comparable form and
102	     * duplicates can be detected by comparing these values. Format validity is enforced
103	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
104	     * the transform the stored value needs.
105	     */
106	    @Named("normalizeTelephone")
107	    default String normalizeTelephone(String telephone) {
108	        return TelephoneNormalizer.toE164(telephone);
109	    }
110	
111	    /**
112	     * Normalize an email address by trimming surrounding whitespace and lower-casing
113	     * it so it is stored and returned in a canonical form. Syntactic validity is
114	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
115	     * the transform the stored value needs.
116	     */
117	    @Named("normalizeEmail")
118	    default String normalizeEmail(String email) {
119	        return email == null ? null : email.trim().toLowerCase();
120	    }
121	
122	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
123	
124	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
125	
126	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
127	        OwnerPageDto ownerPageDto = new OwnerPageDto();
128	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
129	        ownerPageDto.setPage(ownerPage.getNumber());
130	        ownerPageDto.setSize(ownerPage.getSize());
131	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
132	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
133	        return ownerPageDto;
134	    }
135	}
