/**
 * Compute an owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
 * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
 * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
 */
private int computeMembershipLevel(Owner owner) {
    int level = 1;
    if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
        level++;
    }
    if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
        level++;
    }
    return Math.min(level, 3);
}

